/** In-memory catalog storage: every copy succeeds. */
class Storage implements ImportObjectStorage {
    objects = new Map<string, ImportObjectIdentity>();
    async head(target: ImportObjectTarget) { return this.objects.get(`${target.bucket}/${target.key}`) ?? null; }
    async put(target: ImportObjectTarget) { const identity = { etag: '"stage-etag"', versionId: 'stage-version' }; this.objects.set(`${target.bucket}/${target.key}`, identity); return identity; }
    async copy(_source: ImportObjectTarget & ImportObjectIdentity, target: ImportObjectTarget) { const identity = { etag: '"canonical-etag"', versionId: 'canonical-version' }; this.objects.set(`${target.bucket}/${target.key}`, identity); return identity; }
    async delete(target: ImportObjectTarget & ImportObjectIdentity) { this.objects.delete(`${target.bucket}/${target.key}`); }
}

const v2 = (extra: Partial<ImportEmbeddedTagsV2> = {}, identifiers: Partial<ImportEmbeddedTagsV2['identifiers']> = {}): ImportEmbeddedTagsV2 => ({ version: 2, title: null, album: null, artists: [], albumArtists: [],
    label: null, year: null, discNumber: null, trackNumber: null, durationMs: null, identifiers: { barcode: null, catalogNumber: null, isrc: null, musicBrainzReleaseId: null, ...identifiers }, flagged: [], ...extra });
const lengths = [200_000, 210_000];
/** The shared album and album-artist tags of the synthetic files, with each file's duration matching the synthetic release. */
const timed = (index: number) => v2({ album: 'Synthetic Album', albumArtists: ['Synthetic Ensemble'], durationMs: lengths[index] ?? null });
/** An import whose files are confirmed with the given evidence, written directly (no trigger runs); `ready` limits which are. */
async function seeded(count: number, tags: (index: number) => ImportEmbeddedTagsV2, ready = count) {
    const files = Array.from({ length: count }, (_unused, index) => ({ slotId: randomUUID(), filename: `0${index} Secret File ${index}.wav`, relativePath: `Disc 1/0${index} Secret File ${index}.wav`, byteLength: null }));
    const item = (await createAdminImport(by, { operationId: randomUUID(), manifest: { rootLabel: 'Synthetic Secret Folder', files } })).item;
    await projects().updateOne({ _id: new ObjectId(item.id) }, { $set: { media: { assets: item.manifest.files.slice(0, ready).map((file, index) => asset(item.id, file.slotId, file.filename, tags(index))) } } });
    return item.id;
}
function asset(id: string, slotId: string, filename: string, tags: ImportEmbeddedTagsV2) {
    const operationId = randomUUID(), now = new Date();
    return { slotId, operationId, actorId: by, bucket: 'synthetic-private-imports', key: `imports/${id}/${slotId}/${operationId}`, sha256: randomUUID().replace(/-/g, '').repeat(2),
        byteLength: 10, contentType: 'audio/wav', filename, state: 'ready' as const, versionId: 'stage-version', etag: '"stage-etag"', updatedAt: now, leaseOwner: null, leaseUntil: null,
        transferDeadline: null, failureConfirmedAt: null, duration: '0:01', format: 'wav', tags, automatedAt: now,
        representation: { revision: operationId, objectKey: `imports/${id}/${slotId}/${operationId}`, byteLength: 10, durationMs: 1000, seekable: true, format: 'wav-pcm' as const, etag: null, versionId: null },
        recovery: { operationId, expectedRevision: 1, kind: 'upload' as const, actorId: by } };
}

const json = (url: string, body: unknown, status = 200): LookupExchange => ({ url, status, headers: { 'content-type': 'application/json' }, body });
const searchUrl = (query: MusicBrainzReleaseQuery) => musicBrainzUrls.releaseSearch(query).href;
const releaseUrl = (id: string) => musicBrainzUrls.release(id).href;
const searchAnswer = (query: MusicBrainzReleaseQuery, ids: string[]) => json(searchUrl(query), { count: ids.length, offset: 0, releases: ids.map((id, index) => ({ id, title: `Synthetic Release ${index}`, score: 100 - index })) });
type ReleaseOptions = { title?: string; label?: string | null; lengths?: number[]; tracks?: string[]; credits?: [string, string][]; group?: string };
/** A synthetic MusicBrainz release answer: two credited artists, one label, a group first-release date and two tracks. */
const releaseAnswer = (id: string, options: ReleaseOptions = {}) => json(releaseUrl(id), {
    id, title: options.title ?? 'Synthetic Album', status: 'Official', date: '2021-05-01', country: 'JP', barcode: null,
    'artist-credit': (options.credits ?? [['Synthetic Lead', ' & '], ['Synthetic Second', '']]).map(([name, joinphrase], index) => ({ name, joinphrase, artist: { id: mbid(300 + index), name } })),
    'label-info': options.label === null ? [] : [{ 'catalog-number': 'SYN-001', label: { id: mbid(400), name: options.label ?? 'Synthetic Label' } }],
    'release-group': { id: mbid(500), 'primary-type': 'Album', 'first-release-date': options.group ?? '2020-03' },
    media: [{ position: 1, format: 'CD', tracks: (options.lengths ?? lengths).map((length, index) => ({ position: index + 1, number: String(index + 1),
        title: options.tracks?.[index] ?? `Synthetic Track ${index + 1}`, length, recording: { id: mbid(900 + index), length } })) }]
});
const albumQuery = { release: 'Synthetic Album', artist: 'Synthetic Ensemble' };
/** The two planned searches of the synthetic files, the first finding `ids`, and each release's details. */
const answers = (ids: string[], releases: LookupExchange[]) => [searchAnswer(albumQuery, ids), searchAnswer({ release: 'Synthetic Album' }, []), ...releases];
const fixtureClient = (exchanges: LookupExchange[]) => {
    const fixture = fixtureTransport(exchanges);
    return { musicBrainz: createMusicBrainzClient({ gate: immediateGate(), transport: fixture.transport, sleep: async () => undefined }), requests: fixture.requests };
};
async function drain(dependencies: MetadataLookupWorkerDependencies) { for (let tick = 0; tick < 10 && await runMetadataLookupOnce(dependencies); tick++); }
/** Runs the automatic lookup of a seeded import to completion with the given release answers. */
async function looked(id: string, ids: string[], releases: LookupExchange[]) {
    assert.equal((await requestAutomaticMetadataLookup(by, id, 'upload')).reason, 'queued');
    const client = fixtureClient(answers(ids, releases));
    await drain({ musicBrainz: client.musicBrainz });
    return lookup(id);
}
/** Arms a one-shot hook on the next read of an import project, which runs inside the next transaction that reads one. */
function onNextProjectRead(t: { mock: { method: typeof import('node:test').mock.method } }, work: () => Promise<unknown>) {
    let armed = false; const original = Collection.prototype.findOne;
    t.mock.method(Collection.prototype, 'findOne', async function (this: Collection, ...args: unknown[]) {
        if (armed && this.collectionName === 'adminAlbumImports') { armed = false; await work(); }
        return (original as (...values: unknown[]) => unknown).apply(this, args);
    });
    return () => { armed = true; };
}
