    await looked(id, [mbid(1), mbid(2)], [releaseAnswer(mbid(1)), releaseAnswer(mbid(2), { lengths: [1000, 2000] })]);
    await choose(id, 1, keyOf(2));
    await choose(id, 1, null);
    await choose(id, 1, keyOf(1));
    await resolveAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: (await item(id)).revision, run: 1, candidateKey: keyOf(1),
        answers: [{ path: `tracks.${slot}.title`, answer: 'mine', base: 'Typed Title' }] });
    await getAdminImportLookup(by, id);
    assert.deepEqual(await snapshot(), before);

    const storage = new Storage();
