test('a re-rank whose write fails leaves the ranking, gate and values as they were and the confirmation unaffected; the next confirmation re-ranks once', async t => {
    const id = await seeded(2, timed, 1);
    await submit(id);
    const queries = (await lookup(id)).queries.map(query => (query as { query: MusicBrainzReleaseQuery }).query);
    const client = fixtureClient([...queries.map((query, index) => searchAnswer(query, index ? [] : [mbid(1)])), releaseAnswer(mbid(1))]);
    await drain({ musicBrainz: client.musicBrainz });
    assert.deepEqual([(await lookup(id)).ranking!.preselection, (await lookup(id)).applied], [null, null]);
    const sent = client.requests.length, file = (await item(id)).manifest.files[1];
    // The last file is confirmed at the automatic limit, so the trigger re-ranks instead of starting a run.
    await adminImportLookupCollection().updateOne({ _id: new ObjectId(id) }, { $set: { automaticRuns: 3 } });
    await projects().updateOne({ _id: new ObjectId(id) }, { $push: { 'media.assets': asset(id, file.slotId, file.filename, timed(1)) } as never });
    const settled = [await lookup(id), await stored(id)];
    for (const collection of ['adminImportLookups', 'adminAlbumImports']) {
        const original = Collection.prototype.replaceOne;
        const mocked = t.mock.method(Collection.prototype, 'replaceOne', async function (this: Collection, ...args: unknown[]) {
            if (this.collectionName === collection) throw new Error('synthetic write failure');
            return (original as (...values: unknown[]) => unknown).apply(this, args);
        });
        assert.equal((await requestAutomaticMetadataLookup(by, id, 'upload')).reason, 'failed', collection);
        mocked.mock.restore();
        assert.deepEqual([await lookup(id), await stored(id)], settled, collection);
    }
    assert.equal((await requestAutomaticMetadataLookup(by, id, 'upload')).reason, 'limit');
    const record = await lookup(id), doc = await stored(id);
    assert.deepEqual([record.ranking!.preselection?.candidateKey, record.applied?.candidateKey, doc.valueRevision, draftOf(doc).album.title, doc.revision, doc.lookupGate!.fence],
        [keyOf(1), keyOf(1), 1, 'Synthetic Album', (settled[1] as AdminImportDocument).revision, 4]);
    assert.equal(client.requests.length, sent, 'no request');
});

test('a submission and a retry are receipts that replay, are admitted at a revision before another administrator\'s field save, and only the Draft v2 detail lists them', async () => {
    const id = await seeded(2, timed);
    const body = { operationId: randomUUID(), expectedRevision: 1, kind: 'album', text: 'Typed Album' };
    const submitted = await submitAdminImportLookup(by, id, body), first = await lookup(id);
    assert.deepEqual([submitted.receipt, submitted.item.valueRevision, first.run, first.state, first.operationId, first.actorId, first.grantSource, first.input],
        [{ operationId: body.operationId, kind: 'lookup', revision: 2 }, 0, 1, 'queued', body.operationId, by, 'submit', { trigger: 'submitted', submitted: { kind: 'album', text: 'Typed Album' } }]);
    assert.deepEqual((await stored(id)).lookupGate, { fence: 1, run: 1, state: 'queued', blocking: true });
    assert.deepEqual(await submitAdminImportLookup(by, id, body), submitted);
    await assert.rejects(submitAdminImportLookup(by, id, { ...body, text: 'Other Album' }), code('ADMIN_IMPORT_OPERATION_CONFLICT'));
    // A retry while the run may still be sending is refused and records nothing.
    const queued = [await stored(id), await lookup(id)];
    await assert.rejects(retryAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: 2 }), code('ADMIN_IMPORT_LOOKUP_ACTIVE'));
    assert.deepEqual([await stored(id), await lookup(id)], queued);
    // Another administrator's save raises the revision; a retry made before it is still admitted, binding the run's state instead.
    await adminImportLookupCollection().updateOne({ _id: new ObjectId(id) }, { $set: { state: 'unavailable', issue: 'sourceUnavailable' } });
    await editAdminImport(byOther, id, { operationId: randomUUID(), expectedRevision: 2, changes: [{ path: 'album.title', base: '', value: 'Typed Title' }] });
    const retry = { operationId: randomUUID(), expectedRevision: 2 }, retried = await retryAdminImportLookup(by, id, retry), second = await lookup(id);
    assert.deepEqual([retried.receipt?.kind, retried.item.revision, second.run, second.state, second.grantSource, second.queries], ['lookup-retry', 4, 2, 'queued', 'retry', first.queries]);
    assert.deepEqual(await retryAdminImportLookup(by, id, retry), retried);
    await assert.rejects(retryAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: 5 }), code('ADMIN_IMPORT_REVISION_CONFLICT'));
    assert.deepEqual((await item(id)).receipts.map(receipt => receipt.kind), ['create', 'lookup', 'edit', 'lookup-retry']);
    assert.deepEqual(adminImportDto(await stored(id), by).receipts.map(receipt => receipt.kind), ['create', 'edit']);
});

