test('a retry or a choice made before another administrator\'s lookup submission, retry or choice is a revision conflict that writes nothing', async () => {
    const id = await seeded(2, timed);
    await looked(id, [mbid(1), mbid(2)], [releaseAnswer(mbid(1), { label: 'First Label' }), releaseAnswer(mbid(2), { label: 'Second Label' })]);
    const seen = (await item(id)).revision;
    // Another administrator chooses the second candidate meanwhile.
    await choose(id, 1, keyOf(2), byOther);
    let before = [await stored(id), await lookup(id)];
    await assert.rejects(chooseAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: seen, run: 1, candidateKey: keyOf(1) }), code('ADMIN_IMPORT_REVISION_CONFLICT'));
    await assert.rejects(retryAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: seen }), code('ADMIN_IMPORT_REVISION_CONFLICT'));
    assert.deepEqual([await stored(id), await lookup(id)], before);
    // Made after that choice, the same choice is admitted.
    const chosen = await chooseAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: (await item(id)).revision, run: 1, candidateKey: keyOf(1) });
    assert.deepEqual(chosen.item.draft.album.label, { name: 'First Label', musicBrainzId: mbid(400) });
    // Another administrator's submission starts run 2: a retry or a choice made before it is stale, one made after it is admitted.
    const beforeSubmission = chosen.item.revision;
    await submitAdminImportLookup(byOther, id, { operationId: randomUUID(), expectedRevision: beforeSubmission, kind: 'album', text: 'Typed Album' });
    await adminImportLookupCollection().updateOne({ _id: new ObjectId(id) }, { $set: { state: 'unavailable', issue: 'sourceUnavailable' } });
    before = [await stored(id), await lookup(id)];
    await assert.rejects(retryAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: beforeSubmission }), code('ADMIN_IMPORT_REVISION_CONFLICT'));
    await assert.rejects(chooseAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: beforeSubmission, run: 2, candidateKey: null }), code('ADMIN_IMPORT_REVISION_CONFLICT'));
    assert.deepEqual([await stored(id), await lookup(id)], before);
    const retried = await retryAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: (await item(id)).revision });
    assert.deepEqual([retried.receipt?.kind, (await lookup(id)).run], ['lookup-retry', 3]);
});

test('a failed write inside a choice or an answer stores neither the import document nor the lookup record', async t => {
    const id = await seeded(2, timed);
    await editAdminImport(by, id, { operationId: randomUUID(), expectedRevision: 1, changes: [{ path: 'album.label', base: null, value: { name: 'Mine', musicBrainzId: null } }] });
    await looked(id, [mbid(1), mbid(2)], [releaseAnswer(mbid(1), { label: 'First Label' }), releaseAnswer(mbid(2), { label: 'Second Label', title: 'Second Album' })]);
    await choose(id, 1, keyOf(1));
    assert.deepEqual((await lookup(id)).applied!.conflicts.map(conflict => [conflict.path, conflict.answer]), [['album.label', null]]);
    const settled = [await stored(id), await lookup(id)], revision = (settled[0] as AdminImportDocument).revision;
    for (const collection of ['adminAlbumImports', 'adminImportLookups']) {
        const original = Collection.prototype.replaceOne;
        const mocked = t.mock.method(Collection.prototype, 'replaceOne', async function (this: Collection, ...args: unknown[]) {
            if (this.collectionName === collection) throw new Error('synthetic write failure');
            return (original as (...values: unknown[]) => unknown).apply(this, args);
        });
        try {
            await assert.rejects(chooseAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: revision, run: 1, candidateKey: keyOf(2) }), /synthetic write failure/, collection);
            await assert.rejects(resolveAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: revision, run: 1, candidateKey: keyOf(1),
                answers: [{ path: 'album.label', answer: 'lookup', base: { name: 'Mine', musicBrainzId: null } }] }), /synthetic write failure/, collection);
        } finally { mocked.mock.restore(); }
        assert.deepEqual([await stored(id), await lookup(id)], settled, collection);
    }
    // Without the failure, both commit.
    const answered = await resolveAdminImportLookup(by, id, { operationId: randomUUID(), expectedRevision: revision, run: 1, candidateKey: keyOf(1),
        answers: [{ path: 'album.label', answer: 'lookup', base: { name: 'Mine', musicBrainzId: null } }] });
    assert.deepEqual([answered.item.draft.album.label, (await lookup(id)).applied!.conflicts[0].answer], [{ name: 'First Label', musicBrainzId: mbid(400) }, 'lookup']);
});

